{"explanation":"The inscribed angle theorem says that for a fixed chord AB, every point P on the same arc sees AB at the same angle, which is half the central angle AOB. Drag the yellow point P along the circle's major arc and the angle at P stays constant. The label shows it is always half of the central angle.","manimCode":"const R = 2.3;
const C = [-1.5, 0, 0];
const pt = (a) => [C[0] + R*Math.cos(a), C[1] + R*Math.sin(a), 0];

const circle = new Circle({ radius: R, color: BLUE });
circle.moveTo(C);

const aA = Math.PI * 1.15, aB = Math.PI * 1.85; // chord at bottom
const A = pt(aA), B = pt(aB);
const O = C;

const dotA = new Dot({ point: A, color: RED });
const dotB = new Dot({ point: B, color: RED });
const dotO = new Dot({ point: O, color: WHITE });

const chordAB = new Polygon({ vertices: [A, B], color: RED });
chordAB.setStrokeWidth(4).setFillOpacity(0);

const centralA = new Polygon({ vertices: [O, A], color: GRAY });
centralA.setStrokeWidth(2).setFillOpacity(0);
const centralB = new Polygon({ vertices: [O, B], color: GRAY });
centralB.setStrokeWidth(2).setFillOpacity(0);

let ang = Math.PI * 0.5;
const P = new Dot({ point: pt(ang), color: YELLOW, radius: 0.12 });

const sideA = new Polygon({ vertices: [pt(ang), A], color: YELLOW });
sideA.setStrokeWidth(3).setFillOpacity(0);
const sideB = new Polygon({ vertices: [pt(ang), B], color: YELLOW });
sideB.setStrokeWidth(3).setFillOpacity(0);

scene.add(circle, chordAB, centralA, centralB, sideA, sideB, dotA, dotB, dotO, P);

// Angle values
const central = (() => {
  const v1 = [A[0]-O[0], A[1]-O[1]], v2 = [B[0]-O[0], B[1]-O[1]];
  return Math.acos((v1[0]*v2[0]+v1[1]*v2[1]) / (R*R)) * 180 / Math.PI;
})();

let info = null;
function showInfo(deg) {
  if (info) scene.remove(info);
  info = new Text({
    text: 'Inscribed angle APB = ' + deg.toFixed(1) + '°\nCentral angle AOB = ' + central.toFixed(1) + '°\nInscribed = ½ · Central',
    color: WHITE, fontSize: 24
  });
  info.moveTo([4, 1.5, 0]);
  scene.add(info);
}

let arcMark = null;
function update() {
  const [x, y] = P.getCenter();
  // keep P on circle, only on the major arc (above chord)
  let a = Math.atan2(y - C[1], x - C[0]);
  if (a < 0) a += 2*Math.PI;
  // allowed arc: from aB (wrapping) to aA, i.e. outside (aA, aB)
  if (a > aA && a < aB) {
    a = (a - aA < aB - a) ? aA - 0.05 : aB + 0.05 - 2*Math.PI;
  }
  const p = pt(a);
  P.moveTo(p);
  sideA.setVertices([p, A]);
  sideB.setVertices([p, B]);
  const u = [A[0]-p[0], A[1]-p[1]], w = [B[0]-p[0], B[1]-p[1]];
  const cosv = (u[0]*w[0]+u[1]*w[1]) / (Math.hypot(...u) * Math.hypot(...w));
  const deg = Math.acos(Math.max(-1, Math.min(1, cosv))) * 180 / Math.PI;
  showInfo(deg);
  // small arc marker at P
  if (arcMark) scene.remove(arcMark);
  const a1 = Math.atan2(u[1], u[0]), a2 = Math.atan2(w[1], w[0]);
  let d = a2 - a1;
  while (d > Math.PI) d -= 2*Math.PI;
  while (d < -Math.PI) d += 2*Math.PI;
  const verts = [];
  for (let i = 0; i <= 12; i++) {
    const t = a1 + d * i / 12;
    verts.push([p[0] + 0.5*Math.cos(t), p[1] + 0.5*Math.sin(t), 0]);
  }
  arcMark = new Polygon({ vertices: verts, color: ORANGE });
  arcMark.setStrokeWidth(4).setFillOpacity(0);
  scene.add(arcMark);
}

makeDraggable(P, scene, { onDrag: update });
update();

const title = new Text({ text: 'Inscribed Angle Theorem — drag the yellow point', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.5, 0]);
scene.add(title);

await scene.wait(999999);"}

